args.query:
WITH sorted_cs AS (
    SELECT AVG(cognitive_score) as val FROM measurements ORDER BY cognitive_score LIMIT 1 OFFSET (SELECT COUNT(*)/2 FROM measurements)
),
cs_stats AS (SELECT AVG(cognitive_score) as mean_cs FROM measurements,
    (SELECT AVG(CASE WHEN cognitive_score <= (SELECT AVG(cognitive_score) FROM measurements) THEN cognitive_score ELSE 0 END) as q1,
     AVG(CASE WHEN cognitive_score >= (SELECT AVG(cognitive_score) FROM measurements) THEN cognitive_score ELSE 0 END) as q3
    FROM measurements)
)
SELECT * FROM cs_stats;
